def main():
    parts = sys.stdin.read().split()
    if len(parts) >= 2:
        a, b = int(parts[0]), int(parts[1])
        print(f"{oct(a)[2:]} {hex(b)[2:].upper()}")

if __name__ == '__main__':
    main()

